"""
    Inventory support module private methods.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

import csv
import io
from copy import deepcopy
from velocity_communicator.log.log import Log
from velocity_communicator.support_services.private.common_methods import CommonMethods


class InventoryPrivate(object):
    """
        Class with definicion of private methods related to
        Inventory module.
    """
    logger = Log.get_logger("velocityclient")

    def _get_template_info(self, template_name):
        templates = self.get_templates(filter=(f'name::{template_name}'))
        if len(templates["templates"]) != 1:
            raise Exception("There is more than one template!")
        return templates["templates"][0]

    def _connections_to_csv_body(self, connections):
        # Define the header
        header = ["device1", "port1", "place1", "type", "device2", "port2", "place2", "cable"]
        # Convert each dataclass to a row (list of values)
        rows = []
        for con in connections:
            row = [con.device1, con.port1, con.place1, con.type, con.device2, con.port2, con.place2, con.cable]
            rows.append(row)
        return {"header": header, "rows": rows}

    def _get_physical_connections_list(self):
        """
        Gets csv formatted text data of all physical connections from
        given velocity instance, and parses it into a list.
        Method takes around 10 minutes to get data from velocity
        because of the quantity of physical connections.

        """
        connections = []
        csv_data = self.get_physical_connections_csv()
        csv_file = io.StringIO(csv_data)
        reader = csv.DictReader(csv_file)
        for row in reader:
            connections.append(row)
        return connections

    def _get_physical_connections_list_by_name(self, device_name):
        limit = 200
        connection_list = []
        connections = self.get_physical_connections(limit=limit,
                                                    searchString=device_name)
        if connections["total"] == 0:
            msg = f'VC: Could not find any connections for {device_name}! ' \
                  + 'Please check the device name.'
            self.logger.warning(msg)
            raise Exception(msg)
        connection_list.extend(connections["connections"])
        total_all = connections["total"]
        offset = limit
        if total_all > limit:
            while offset < total_all:
                connections = self.get_physical_connections(limit=limit,
                                                            searchString=device_name,
                                                            offset=offset)
                connection_list.extend(connections["connections"])
                offset += limit
        return connection_list

    def _get_folder_info(self, folder_name):
        folder_data = self.get_inventory_folders()
        return self._find_folder_by_name(folder_data, folder_name)

    def _find_folder_by_name(self, folder_data, name):
        if folder_data["name"] == name:
            return folder_data
        for subfolder in folder_data.get("folders", []):
            result = self._find_folder_by_name(subfolder, name)
            if result:
                return result
        return None

    def _generate_device_ports_body(self, ports_data):

        ports_list = []
        for port in ports_data:
            properties = []
            for property in port["properties"]:
                properties.append({
                    "definitionId": property["definitionId"]
                })
            ports_list.append({
                "name": port["name"],
                "description": port["description"],
                "templateId": port["templateId"],
                "groupId": port["groupId"],
                "properties": properties
            })
        return ports_list

    @staticmethod
    def _parse_and_remove_duplicate_connections(connections, device_order=None):
        """
        Removes duplicate connections and sorts by device_order if provided.
        """
        unique_pairs = set()
        unique_connections = []
        device_index = {name: idx for idx, name in enumerate(device_order)} if device_order else {}

        for connection in connections:
            # Identify the pair regardless of direction
            pair = tuple(sorted([
                (connection.device1, connection.port1, connection.place1),
                (connection.device2, connection.port2, connection.place2)
            ]))
            if pair not in unique_pairs:
                unique_pairs.add(pair)
                # If device_order is given, ensure device1 is from device_order if possible
                if device_order:
                    # If device2 is in device_order and device1 is not, or device2 comes first, swap
                    idx1 = device_index.get(connection.device1, float('inf'))
                    idx2 = device_index.get(connection.device2, float('inf'))
                    if idx2 < idx1:
                        # Swap device1 and device2 fields
                        connection = deepcopy(connection)
                        (connection.device1, connection.port1, connection.place1,
                         connection.device2, connection.port2, connection.place2) = (
                            connection.device2, connection.port2, connection.place2,
                            connection.device1, connection.port1, connection.place1
                        )
                unique_connections.append(connection)

        if device_order:
            def sort_key(con):
                device_idx = device_index.get(con.device1, len(device_order))
                port_idx = CommonMethods.natural_keys(con.port1)
                return device_idx, port_idx

            unique_connections.sort(key=sort_key)
        else:
            unique_connections = sorted(unique_connections,
                                        key=lambda x: (x.device1, CommonMethods.natural_keys(x.port1)))

        return unique_connections
